class Solution:
    def longestSteady(self, readings: List[int], limit: int) -> int:
        n, best = len(readings), 0
        for i in range(n):
            hi = lo = readings[i]
            j = i
            while j < n and max(hi, readings[j]) - min(lo, readings[j]) <= limit:
                hi, lo = max(hi, readings[j]), min(lo, readings[j])
                j += 1
            best = max(best, j - i)
        return best

