class Solution {
    public int longestSteady(int[] readings, int limit) {
        int n = readings.length, best = 0;
        for (int i = 0; i < n; i++) {
            int hi = readings[i], lo = readings[i], j = i;
            while (j < n && (long) Math.max(hi, readings[j]) - Math.min(lo, readings[j]) <= limit) {
                hi = Math.max(hi, readings[j]);
                lo = Math.min(lo, readings[j++]);
            }
            best = Math.max(best, j - i);
        }
        return best;
    }
}

