int longestSteady(int* readings, int readingsSize, int limit) {
    int n = readingsSize, best = 0;
    for (int i = 0; i < n; i++) {
        int hi = readings[i], lo = readings[i], j = i;
        while (j < n) {
            int h = readings[j] > hi ? readings[j] : hi, l = readings[j] < lo ? readings[j] : lo;
            if ((long long) h - l > limit) break;
            hi = h; lo = l; j++;
        }
        if (j - i > best) best = j - i;
    }
    return best;
}

