class Solution {
    public int longestSteady(int[] readings, int limit) {
        Deque<Integer> hi = new ArrayDeque<>(), lo = new ArrayDeque<>();
        int left = 0, best = 0;
        for (int i = 0; i < readings.length; i++) {
            int v = readings[i];
            while (!hi.isEmpty() && readings[hi.peekLast()] <= v) hi.pollLast();
            hi.addLast(i);
            while (!lo.isEmpty() && readings[lo.peekLast()] >= v) lo.pollLast();
            lo.addLast(i);
            while (readings[hi.peekFirst()] - readings[lo.peekFirst()] > limit) {
                left++;
                if (hi.peekFirst() < left) hi.pollFirst();
                if (lo.peekFirst() < left) lo.pollFirst();
            }
            best = Math.max(best, i - left + 1);
        }
        return best;
    }
}

