class Solution {
public:
    int longestSteady(vector<int>& readings, int limit) {
        deque<int> hi, lo;
        int left = 0, best = 0;
        for (int i = 0; i < (int) readings.size(); i++) {
            int v = readings[i];
            while (!hi.empty() && readings[hi.back()] <= v) hi.pop_back();
            hi.push_back(i);
            while (!lo.empty() && readings[lo.back()] >= v) lo.pop_back();
            lo.push_back(i);
            while (readings[hi.front()] - readings[lo.front()] > limit) {
                left++;
                if (hi.front() < left) hi.pop_front();
                if (lo.front() < left) lo.pop_front();
            }
            best = max(best, i - left + 1);
        }
        return best;
    }
};

