int longestSteady(int* readings, int readingsSize, int limit) {
    int* hi = malloc(readingsSize * sizeof(int));
    int* lo = malloc(readingsSize * sizeof(int));
    int hh = 0, ht = 0, lh = 0, lt = 0, left = 0, best = 0;
    for (int i = 0; i < readingsSize; i++) {
        int v = readings[i];
        while (ht > hh && readings[hi[ht - 1]] <= v) ht--;
        hi[ht++] = i;
        while (lt > lh && readings[lo[lt - 1]] >= v) lt--;
        lo[lt++] = i;
        while (readings[hi[hh]] - readings[lo[lh]] > limit) {
            left++;
            if (hi[hh] < left) hh++;
            if (lo[lh] < left) lh++;
        }
        if (i - left + 1 > best) best = i - left + 1;
    }
    free(hi); free(lo);
    return best;
}
